// OPD Saathi sends: { type, at, hospital, data: { token, firstName, dept,
// rooms, floor, lang, mobile?, room?, where?, by? } }
// Change these two settings:
const SETTINGS = {
  telegramChatId: 'PUT-YOUR-STAFF-GROUP-CHAT-ID', // staff group that gets urgent alerts
  countryCode: '+91',
  smsProvider: 'fast2sms', // 'fast2sms' (India) or 'twilio'
  fast2smsKey: 'PUT-YOUR-FAST2SMS-API-KEY', // fast2sms.com -> Dev API
};

const FLOOR = { 0: ['ground floor', 'भूतल'], 1: ['first floor', 'पहली मंज़िल'], 2: ['second floor', 'दूसरी मंज़िल'] };
const PLACE = {
  g_entrance: 'Main entrance', g_reg: 'Registration counters', g_help: 'Help desk', g_emergency: 'Emergency',
  g_pharmacy: 'Pharmacy', g_lab: 'Laboratory', g_xray: 'X-ray', g_water: 'Drinking water', g_toilets: 'Toilets (ground floor)',
  g_wheelchair: 'Wheelchair point', g_lift: 'Lift (ground floor)', f1_waitA: 'Waiting hall A', f1_toilets: 'Toilets (first floor)',
  f1_lift: 'Lift (first floor)', f1_opd1: 'Room 1', f1_opd2: 'Room 2', f1_opd3: 'Room 3', f1_opd4: 'Room 4',
  f1_opd5: 'Room 5', f1_opd6: 'Room 6', f1_opd7: 'Room 7', f1_opd8: 'Room 8', f2_nurses: "Nurses' station",
  f2_ward4: 'Ward 4', f2_ward5: 'Ward 5', f2_ward6: 'Ward 6', f2_lift: 'Lift (second floor)',
};

const out = [];
for (const item of $input.all()) {
  let body = item.json.body ?? item.json;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { body = {}; }
  }
  const type = body.type || 'unknown';
  const d = body.data || {};
  const hi = d.lang === 'hi';
  const floor = FLOOR[d.floor] ? FLOOR[d.floor][hi ? 1 : 0] : '';
  const rooms = (d.rooms || []).join(hi ? ' या ' : ' or ');
  let route = 'log';
  let smsText = '';
  let staffText = '';

  if (type === 'urgent_flag') {
    route = 'staff';
    staffText = [
      'URGENT: help needed at City District Hospital',
      `${d.token ? 'Token ' + d.token + ' - ' : ''}${d.firstName || 'Person not registered'}`,
      `Where: ${PLACE[d.where] || d.where || 'not given'}`,
      `Sent by: ${d.by === 'helper' ? 'a helper' : 'the patient'}`,
      'Please go now, then press "Mark as seen" on the dashboard.',
    ].join('\n');
  } else if (type === 'charges_added' && d.mobile && d.amount > 0) {
    route = SETTINGS.smsProvider === 'twilio' ? 'twilio' : 'fast2sms';
    smsText = hi
      ? `OPD साथी: कृपया अपनी जाँचों के लिए ₹${d.amount} दें (टोकन ${d.token}), फ़ोन से या काउंटर पर।`
      : `OPD Saathi: Please pay Rs ${d.amount} for your tests (token ${d.token}), on your phone or at the counter.`;
  } else if (type === 'payment_received' && d.mobile) {
    route = SETTINGS.smsProvider === 'twilio' ? 'twilio' : 'fast2sms';
    smsText = hi
      ? `OPD साथी: ₹${d.amount} का भुगतान मिला (टोकन ${d.token})। रसीद ${d.receipt}।`
      : `OPD Saathi: Payment received, Rs ${d.amount} for token ${d.token}. Receipt ${d.receipt}.`;
  } else if ((type === 'turn_near' || type === 'token_called' || type === 'no_show') && d.mobile) {
    route = SETTINGS.smsProvider === 'twilio' ? 'twilio' : 'fast2sms';
    if (type === 'turn_near') {
      smsText = hi
        ? `OPD साथी: आपकी बारी पास है (टोकन ${d.token})। कृपया ${floor} पर कमरा ${rooms} के पास जाएँ।`
        : `OPD Saathi: Your turn is close (token ${d.token}). Please go to Room ${rooms} on the ${floor}.`;
    } else if (type === 'token_called') {
      smsText = hi
        ? `OPD साथी: टोकन ${d.token}, कृपया अभी ${floor} पर कमरा ${d.room} में जाएँ।`
        : `OPD Saathi: Token ${d.token}, please go to Room ${d.room} on the ${floor} now.`;
    } else {
      smsText = hi
        ? `OPD साथी: हमने टोकन ${d.token} बुलाया, पर आप नहीं मिले। कृपया सहायता केंद्र पर बात करें।`
        : `OPD Saathi: We called token ${d.token} but could not find you. Please talk to the help desk.`;
    }
  }

  out.push({
    json: {
      type,
      route,
      smsText,
      staffText,
      mobileE164: d.mobile ? SETTINGS.countryCode + d.mobile : '',
      mobile10: d.mobile || '',
      unicode: hi, // Hindi text needs a Unicode SMS
      fast2smsKey: SETTINGS.fast2smsKey,
      telegramChatId: SETTINGS.telegramChatId,
      data: d,
    },
  });
}
return out;

// Counts today's events (kept between runs while the workflow is active).
const s = $getWorkflowStaticData('global');
const day = new Date().toISOString().slice(0, 10);
if (s.day !== day) { s.day = day; s.counts = {}; }
for (const item of $input.all()) s.counts[item.json.type] = (s.counts[item.json.type] || 0) + 1;
return [{ json: { day, counts: s.counts } }];
